def getLucky(s: str, k: int) -> int:
    # Step 1: Convert each character to its position in the alphabet and concatenate
    digits = ''
    for ch in s:
        # 'a' -> 1, ..., 'z' -> 26
        digits += str(ord(ch) - ord('a') + 1)

    # Step 2: Apply the sum-of-digits transformation k times
    for _ in range(k):
        total = 0
        for d in digits:
            total += int(d)
        digits = str(total)

    return int(digits)
